import{C as e,L as t,c as n,d as r,g as i,p as a,t as o,tt as s,u as c}from"./_plugin-vue_export-helper-Dz015xqO.js";import{H as l,I as u,L as d,W as f}from"./index-BgYPVwZB.js";var p={class:`page`},m={class:`card stack small`},h=o(i({__name:`About`,setup(i){let o=f();function h(){l.reset(),location.reload()}return(i,l)=>(e(),r(`section`,p,[n(`button`,{class:`back`,onClick:l[0]||=e=>t(o).back()},`‹ Back`),l[4]||=a(`<h1 data-v-82a239c0>How Stub works</h1><div class="card stack" data-v-82a239c0><div class="step" data-v-82a239c0><b data-v-82a239c0>1</b><p data-v-82a239c0><b data-v-82a239c0>Host makes an event</b> — name, date, price in NIM or USDT, and their own payout address. The whole event is packed into one share link. No sign-up, no server.</p></div><div class="step" data-v-82a239c0><b data-v-82a239c0>2</b><p data-v-82a239c0><b data-v-82a239c0>Guests pay in Nimiq Pay</b> — one tap, confirmed in Nimiq Pay&#39;s own dialog. NIM goes wallet-to-wallet with a public memo like <span class="mono" data-v-82a239c0>STUB:7QK3M2XA:2</span> so the payment is the ticket.</p></div><div class="step" data-v-82a239c0><b data-v-82a239c0>3</b><p data-v-82a239c0><b data-v-82a239c0>Ticket = QR of the payment</b> — the guest&#39;s ticket is the transaction hash. It shows &quot;Confirmed&quot; once the blockchain has it.</p></div><div class="step" data-v-82a239c0><b data-v-82a239c0>4</b><p data-v-82a239c0><b data-v-82a239c0>Check in at the door</b> — the host scans the QR. Stub checks the chain: paid to the host, right event, enough paid, confirmed. First scan wins, so screenshots can&#39;t get in twice.</p></div></div><div class="card stack small" data-v-82a239c0><h3 data-v-82a239c0>Privacy &amp; money</h3><p data-v-82a239c0>Stub never holds funds and has no backend. Events, tickets and check-ins are stored only on your phone. Payments and memos are public on the Nimiq blockchain (or Polygon for USDT). Chain lookups use public RPC servers (nimiqwatch.com, publicnode.com).</p><p data-v-82a239c0>USDT tickets are sent on Polygon and need a little POL for the network fee. Because Polygon transfers carry no memo, a USDT ticket is matched to an event by organizer address, amount and time.</p></div>`,3),n(`div`,m,[l[2]||=n(`h3`,null,`Demo mode`,-1),l[3]||=n(`p`,{class:`muted`},`Try every screen in a normal browser with fake payments. Nothing touches a real wallet.`,-1),n(`button`,{class:`btn ghost`,onClick:l[1]||=e=>t(u)(!t(d).demo)},s(t(d).demo?`Turn demo mode off`:`Turn demo mode on`),1),t(d).demo?(e(),r(`button`,{key:0,class:`btn ghost small`,onClick:h},`Clear demo payments`)):c(``,!0)]),l[5]||=n(`p`,{class:`muted small`},`Open source (MIT). Built on the Nimiq Pay Mini Apps Framework.`,-1)]))}}),[[`__scopeId`,`data-v-82a239c0`]]);export{h as default};